let original = {};
try {
  original = $('IF - Telegram Voice?').item.json || {};
} catch (e) {
  original = $input.first().json || {};
}

const transcriptCandidate =
  $input.first().json.text ??
  $input.first().json.transcription ??
  $input.first().json.transcript ??
  $input.first().json.response?.text ??
  $input.first().json.data?.text ??
  '';

const transcript = String(transcriptCandidate || '').trim();

const output = {
  ...original,
  message: {
    ...(original.message || {}),
    text: transcript || original.message?.caption || ''
  },
  voice_transcription: {
    success: transcript.length > 0,
    text: transcript,
    source: 'openai'
  }
};

return [output];

// Channel Normalizer - Unify input from all channels
const input = $input.first().json;
const nodeName = $input.first().$node?.name || 'unknown';

let channel = 'web';
let session_id = '';
let user_identifier = '';
let message_text = '';
let message_type = 'text';
let attachments = [];
let metadata = {};

// Detect channel and normalize
if (nodeName.includes('Web Chat') || input.chatInput) {
  channel = 'web';
  session_id = input.sessionId || `web_${Date.now()}`;
  user_identifier = input.sessionId || input.user_phone || '';
  message_text = input.chatInput || input.text || '';
  metadata = { source: 'web_chat', original: input };
}
else if (nodeName.includes('WhatsApp') || input.entry) {
  channel = 'whatsapp';
  const entry = input.entry?.[0]?.changes?.[0]?.value;
  const msg = entry?.messages?.[0] || {};
  session_id = msg.from || `wa_${Date.now()}`;
  user_identifier = msg.from ? `+${msg.from}` : '';
  message_text = msg.text?.body || msg.caption || '';
  message_type = msg.type || 'text';
  if (msg.image || msg.document || msg.audio) {
    attachments.push({ type: msg.type, id: msg[msg.type]?.id });
  }
  metadata = { source: 'whatsapp', wa_id: entry?.metadata?.phone_number_id, original: input };
}
else if (nodeName.includes('Telegram') || input.message?.chat) {
  channel = 'telegram';
  const msg = input.message || {};
  session_id = String(msg.chat?.id || `tg_${Date.now()}`);
  user_identifier = msg.from?.username ? `@${msg.from.username}` : String(msg.from?.id || '');
  message_text = msg.text || msg.caption || '';
  message_type = msg.photo ? 'image' : msg.document ? 'document' : msg.voice ? 'voice' : 'text';
  metadata = { source: 'telegram', chat_id: msg.chat?.id, user_id: msg.from?.id, original: input };
}
else if (nodeName.includes('Email') || input.from || input.subject) {
  channel = 'email';
  session_id = input.messageId || `email_${Date.now()}`;
  user_identifier = input.from || input.sender || '';
  message_text = input.text || input.body || input.subject || '';
  metadata = { source: 'email', subject: input.subject, original: input };
}

return [{
  channel,
  session_id,
  sessionId: session_id,
  user_identifier,
  message_text: message_text.trim(),
  message_type,
  attachments,
  timestamp: new Date().toISOString(),
  metadata
}];

// Extract phone number from various identifier formats
const input = $input.first().json;
let user_phone = '';
let user_email = '';
const identifier = input.user_identifier || '';

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (emailPattern.test(identifier)) {
  user_email = identifier;
} else {
  const cleaned = identifier.replace(/[^\d+]/g, '');
  if (cleaned.length >= 8) {
    user_phone = cleaned.startsWith('+') ? cleaned : `+${cleaned}`;
  }
}

if (!user_phone && !user_email && input.channel === 'telegram') {
  user_phone = `telegram:${input.metadata?.user_id || input.session_id}`;
}

// TEST MODE ONLY
user_phone='+971556241060';
return [{
  ...input,
  user_phone,
  user_email,
  user_text: input.message_text
}];

// Extract and validate user from API response
const res = $input.first().json;
let prevData = {};
try {
  prevData = $('Extract User Identifiers').item.json || {};
} catch (e) {
  prevData = {};
}
let u = null;

if (Array.isArray(res)) u = res.length > 0 ? res[0] : null;
else if (res && typeof res === 'object' && Array.isArray(res.body)) u = res.body.length > 0 ? res.body[0] : null;
else if (res && typeof res === 'object' && Object.keys(res).length > 0 && res.id) u = res;

if (!u) {
  return [{ 
    auth_ok: false, 
    user: null,
    is_admin: false,
    ...prevData
  }];
}

const isVip = u.tradingVolume > 1000000 || u.totalDeposits > 50000 || u.isIb === true;
const tags = Array.isArray(u.tags) ? u.tags : [];
const isAdmin = tags.some((tag) => {
  const normalized = String(tag || '').trim().toLowerCase();
  return normalized === 'isadmin' || normalized === 'is admin';
});

return [{
  auth_ok: true,
  is_admin: isAdmin,
  user: {
    id: u.id ?? null,
    managerId: u.managerId ?? null,
    country: u.country ?? null,
    firstName: u.firstName ?? null,
    lastName: u.lastName ?? null,
    fullName: `${u.firstName || ''} ${u.lastName || ''}`.trim() || 'Valued Client',
    email: u.email ?? null,
    phone: u.phone ?? null,
    language: u.language ?? 'en',
    registrationDate: u.registrationDate ?? null,
    lastLoginDate: u.lastLoginDate ?? null,
    status: u.status ?? null,
    isIb: u.isIb ?? false,
    isVip: isVip,
    isAdmin: isAdmin,
    tags: tags,
    verified: u.verified ?? null,
    tradingStatus: u.tradingStatus ?? null,
    lastDepositDate: u.lastDepositDate ?? null,
    nationality: u.nationality ?? null
  },
  ...prevData
}];

// Language Detection using simple heuristics
const text = $input.first().json.user_text || '';

const patterns = {
  ar: /[\u0600-\u06FF\u0750-\u077F]/,
  fa: /[\u0600-\u06FF]/,
  zh: /[\u4E00-\u9FFF]/,
  ja: /[\u3040-\u309F\u30A0-\u30FF]/,
  ko: /[\uAC00-\uD7AF]/,
  ru: /[\u0400-\u04FF]/,
  hi: /[\u0900-\u097F]/,
  th: /[\u0E00-\u0E7F]/
};

let detected_language = 'en';
let confidence = 0.5;

for (const [lang, pattern] of Object.entries(patterns)) {
  if (pattern.test(text)) {
    detected_language = lang;
    confidence = 0.9;
    break;
  }
}

if (detected_language === 'en') {
  const commonEnglish = /\b(the|is|are|have|has|what|how|when|where|why|can|could|would|please|thanks|thank|hello|hi|help)\b/i;
  if (commonEnglish.test(text)) {
    confidence = 0.85;
  }
}

const userLang = $input.first().json.user?.language;
if (confidence < 0.7 && userLang) {
  detected_language = userLang;
  confidence = 0.6;
}

return [{
  ...$input.first().json,
  detected_language,
  language_confidence: confidence
}];

let input = {};
try {
  input = $('Language Detector').item.json || {};
} catch (e) {
  input = $input.first().json || {};
}
const sentimentRaw = $input.first().json.text || $input.first().json.response || '{}';

let sentiment = { sentiment: 'neutral', score: 0, is_urgent: false, confidence: 0.5 };

try {
  let jsonStr = sentimentRaw;
  const jsonMatch = sentimentRaw.match(/```json?\s*([\s\S]*?)```/) || sentimentRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) { jsonStr = jsonMatch[1] || jsonMatch[0]; }
  sentiment = JSON.parse(jsonStr.trim());
} catch (e) {
  const text = (input.user_text || '').toLowerCase();
  if (/angry|furious|terrible|worst|scam|fraud|steal|ridiculous/i.test(text)) {
    sentiment = { sentiment: 'angry', score: -0.8, is_urgent: true, confidence: 0.7 };
  } else if (/frustrated|annoyed|disappointed|upset|problem|issue|not working/i.test(text)) {
    sentiment = { sentiment: 'frustrated', score: -0.5, is_urgent: false, confidence: 0.7 };
  } else if (/urgent|asap|immediately|emergency|critical|help now/i.test(text)) {
    sentiment = { sentiment: 'urgent', score: -0.3, is_urgent: true, confidence: 0.8 };
  } else if (/thank|great|excellent|amazing|love|happy|pleased/i.test(text)) {
    sentiment = { sentiment: 'positive', score: 0.7, is_urgent: false, confidence: 0.7 };
  }
}

return [{
  ...input,
  sentiment: sentiment.sentiment,
  sentiment_score: sentiment.score,
  is_urgent: sentiment.is_urgent,
  sentiment_confidence: sentiment.confidence
}];

let input = {};
try {
  input = $('Parse Sentiment').item.json || {};
} catch (e) {
  input = $input.first().json || {};
}
const intentRaw = $input.first().json.text || $input.first().json.response || '{}';

let intent = { intent: 'general_chat', confidence: 0.5, sub_intent: null };

try {
  let jsonStr = intentRaw;
  const jsonMatch = intentRaw.match(/```json?\s*([\s\S]*?)```/) || intentRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) { jsonStr = jsonMatch[1] || jsonMatch[0]; }
  intent = JSON.parse(jsonStr.trim());
} catch (e) {
  const text = (input.user_text || '').toLowerCase();
  if (/balance|equity|margin|account.*status|my account/i.test(text)) {
    intent = { intent: 'account_inquiry', confidence: 0.8 };
  } else if (/position|trade|order|buy|sell|lot|pip/i.test(text)) {
    intent = { intent: 'trading_question', confidence: 0.8 };
  } else if (/deposit|withdraw|transfer|fund|payment/i.test(text)) {
    intent = { intent: 'deposit_withdrawal', confidence: 0.85 };
  } else if (/price|market|eurusd|gold|bitcoin|forecast/i.test(text)) {
    intent = { intent: 'market_analysis', confidence: 0.8 };
  } else if (/human|agent|person|manager|supervisor|speak.*someone/i.test(text)) {
    intent = { intent: 'escalation_request', confidence: 0.95 };
  } else if (/document|kyc|verify|passport|id|proof/i.test(text)) {
    intent = { intent: 'document_verification', confidence: 0.85 };
  } else if (/bonus|promotion|offer|referral/i.test(text)) {
    intent = { intent: 'promotions', confidence: 0.8 };
  } else if (/login|password|platform|mt4|mt5|not working|error|crash/i.test(text)) {
    intent = { intent: 'technical_support', confidence: 0.8 };
  } else if (/complaint|unhappy|problem|issue|terrible|disappointed/i.test(text)) {
    intent = { intent: 'complaint', confidence: 0.75 };
  }
}

return [{
  ...input,
  intent: intent.intent,
  intent_confidence: intent.confidence,
  sub_intent: intent.sub_intent || null
}];

