-- Ensure table exists with all required columns
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'user_configs') THEN
    CREATE TABLE user_configs (
      id SERIAL PRIMARY KEY,
      user_phone VARCHAR(30) UNIQUE NOT NULL,
      client_id INTEGER,
      system_prompt TEXT,
      preferred_language VARCHAR(10) DEFAULT 'en',
      communication_style VARCHAR(30) DEFAULT 'friendly_support',
      is_vip BOOLEAN DEFAULT FALSE,
      is_ib BOOLEAN DEFAULT FALSE,
      verification_status VARCHAR(20) DEFAULT 'pending',
      last_seen_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
      last_channel VARCHAR(20),
      total_interactions INTEGER DEFAULT 0,
      notification_enabled BOOLEAN DEFAULT TRUE,
      proactive_alerts_enabled BOOLEAN DEFAULT TRUE,
      created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
      updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
    );
  ELSE
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'client_id') THEN ALTER TABLE user_configs ADD COLUMN client_id INTEGER; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'preferred_language') THEN ALTER TABLE user_configs ADD COLUMN preferred_language VARCHAR(10) DEFAULT 'en'; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'communication_style') THEN ALTER TABLE user_configs ADD COLUMN communication_style VARCHAR(30) DEFAULT 'friendly_support'; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'is_vip') THEN ALTER TABLE user_configs ADD COLUMN is_vip BOOLEAN DEFAULT FALSE; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'last_channel') THEN ALTER TABLE user_configs ADD COLUMN last_channel VARCHAR(20); END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'total_interactions') THEN ALTER TABLE user_configs ADD COLUMN total_interactions INTEGER DEFAULT 0; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'system_prompt') THEN ALTER TABLE user_configs ADD COLUMN system_prompt TEXT; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'is_ib') THEN ALTER TABLE user_configs ADD COLUMN is_ib BOOLEAN DEFAULT FALSE; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'verification_status') THEN ALTER TABLE user_configs ADD COLUMN verification_status VARCHAR(20) DEFAULT 'pending'; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'notification_enabled') THEN ALTER TABLE user_configs ADD COLUMN notification_enabled BOOLEAN DEFAULT TRUE; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'proactive_alerts_enabled') THEN ALTER TABLE user_configs ADD COLUMN proactive_alerts_enabled BOOLEAN DEFAULT TRUE; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'created_at') THEN ALTER TABLE user_configs ADD COLUMN created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(); END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'updated_at') THEN ALTER TABLE user_configs ADD COLUMN updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(); END IF;
  END IF;
  BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'user_configs' AND column_name = 'system_prompt' AND is_nullable = 'NO') THEN
      ALTER TABLE user_configs ALTER COLUMN system_prompt DROP NOT NULL;
    END IF;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
END $$;

INSERT INTO user_configs (user_phone, client_id, preferred_language, communication_style, is_vip, last_seen_at, last_channel, total_interactions, system_prompt)
VALUES ('{{ $json.user_phone }}', {{ $json.user?.id ? $json.user.id : 'NULL' }}, '{{ $json.detected_language }}', 'friendly_support', {{ $json.user?.isVip || false }}, NOW(), '{{ $json.channel }}', 1, NULL)
ON CONFLICT (user_phone)
DO UPDATE SET last_seen_at = NOW(), last_channel = EXCLUDED.last_channel, total_interactions = user_configs.total_interactions + 1, preferred_language = COALESCE(NULLIF(EXCLUDED.preferred_language, 'en'), user_configs.preferred_language), client_id = COALESCE(EXCLUDED.client_id, user_configs.client_id), is_vip = COALESCE(EXCLUDED.is_vip, user_configs.is_vip);

