let context = {};
try {
  const parseIntentItems = $('Parse Intent').all();
  if (parseIntentItems?.length) {
    const pairedItem = $input.first().pairedItem;
    if (pairedItem?.item?.length) {
      const sourceIndex = pairedItem.item[0].index || 0;
      context = parseIntentItems[sourceIndex]?.json || parseIntentItems[0].json || {};
    } else context = parseIntentItems[0].json || {};
  } else context = $('Parse Intent').item.json || {};
} catch (e) { context = $input.first().json || {}; }

const dbConfig = $input.first().json || {};
const userText = String(context.user_text || context.message_text || '').trim();
const intent = String(context.intent || 'general_chat');
const intentConfidence = Number(context.intent_confidence || 0);

const patterns = [
  { c: 'account', r: /\b(balance|equity|margin|account|wallet|login|account type|account status)\b/i },
  { c: 'trading', r: /\b(trade|trading|position|order|lot|pip|open position|history)\b/i },
  { c: 'funding', r: /\b(deposit|withdraw|withdrawal|transfer|payment|funding)\b/i },
  { c: 'platform', r: /\b(mt4|mt5|platform|server|connection|terminal|password)\b/i },
  { c: 'kyc', r: /\b(kyc|verify|verification|document|passport|id|proof)\b/i },
  { c: 'promo', r: /\b(promotion|bonus|offer|referral|campaign)\b/i },
  { c: 'market', r: /\b(price|market|news|calendar|nfp|fomc|rates|eurusd|xauusd|gold|bitcoin|btc|eth|forex)\b/i },
  { c: 'support', r: /\b(agent|human|manager|supervisor|support|ticket|callback)\b/i },
  { c: 'general_broker', r: /\b(cms prime|broker|spread|commission|leverage)\b/i }
];
let scopeCategory = 'out_of_scope';
for (const p of patterns) { if (p.r.test(userText)) { scopeCategory = p.c; break; } }
const inScopeByIntent = new Set(['account_inquiry','trading_question','technical_support','complaint','deposit_withdrawal','market_analysis','document_verification','promotions','escalation_request','general_chat']);
if (scopeCategory === 'out_of_scope' && inScopeByIntent.has(intent) && intentConfidence >= 0.55) scopeCategory = intent === 'general_chat' ? 'general_broker' : 'support';
const in_scope = scopeCategory !== 'out_of_scope' && userText.length > 0;

const toolMatrix = {
  account_inquiry: ['get_account_summary'],
  trading_question: ['get_open_positions','get_trade_history'],
  technical_support: ['get_platform_status','submit_support_ticket'],
  complaint: ['submit_support_ticket','schedule_callback'],
  deposit_withdrawal: ['get_transactions'],
  market_analysis: ['get_market_prices','get_market_news','get_economic_calendar'],
  document_verification: ['get_document_status'],
  promotions: ['get_promotions','search_faq'],
  escalation_request: ['submit_support_ticket','schedule_callback'],
  general_chat: ['search_faq']
};
const allowed_tools = in_scope ? (toolMatrix[intent] || ['search_faq']) : [];
const requires_tools = in_scope && allowed_tools.length > 0;
const refusal_message = "I don't have enough knowledge about that. I can only help with CMS Prime account, trading, platform, funding, verification, promotions, and market tools.";
const safe_fallback_message = "I couldn't retrieve reliable data right now. Please try again or contact support.";
const router_status = userText ? 'ok' : 'degraded';

const shouldEscalate = (() => {
  if (!in_scope) return { escalate: false, reason: null };
  if (intent === 'escalation_request') return { escalate: true, reason: 'user_requested' };
  if (context.sentiment_score < -0.6 && context.sentiment === 'angry') return { escalate: true, reason: 'negative_sentiment' };
  if (context.user?.isVip && intent === 'complaint') return { escalate: true, reason: 'vip_complaint' };
  if ((dbConfig.recent_escalations || 0) >= 3) return { escalate: true, reason: 'recurring_issues' };
  return { escalate: false, reason: null };
})();

const basePrompt = `You are Alex from CMS Prime Support. STRICT POLICY: (1) Never guess, infer, or fabricate facts. (2) For account/market/platform/funding/document/promotion data you MUST call tools first. (3) If tool data is missing or unreliable, respond exactly: "${safe_fallback_message}". (4) If request is out of CMS Prime scope, respond exactly: "${refusal_message}". (5) Do not answer unrelated questions.`;
const intentGuidance = {
  account_inquiry: 'Call get_account_summary first.',
  trading_question: 'Call get_open_positions or get_trade_history first.',
  deposit_withdrawal: 'Call get_transactions first.',
  market_analysis: 'Call get_market_prices/get_market_news/get_economic_calendar first.',
  technical_support: 'Call get_platform_status first.',
  document_verification: 'Call get_document_status first.',
  promotions: 'Call get_promotions or search_faq first.',
  escalation_request: 'Offer submit_support_ticket or schedule_callback.',
  complaint: 'Be empathetic then offer escalation tools.',
  general_chat: 'Use search_faq for company/product questions.'
};
const system_prompt = basePrompt + ' ' + (intentGuidance[intent] || 'Use tools before factual answers.');

return [{
  ...context,
  user_text: userText,
  system_prompt,
  selected_persona: dbConfig.active_persona || 'friendly_support',
  should_escalate: shouldEscalate.escalate,
  escalation_reason: shouldEscalate.reason,
  db_config: dbConfig,
  in_scope,
  scope_category: scopeCategory,
  requires_tools,
  allowed_tools,
  refusal_message,
  safe_fallback_message,
  router_status
}];

const context = $input.first().json;
const reason = context.escalation_reason;

let escalationMessage = '';

switch (reason) {
  case 'user_requested':
    escalationMessage = `I understand you'd like to speak with a human agent. Let me connect you with one of our specialists who can provide more personalized assistance.\n\nIn the meantime, I'm creating a priority support ticket so our team has all the context they need.`;
    break;
  case 'negative_sentiment':
    escalationMessage = `I can see you're having a frustrating experience, and I'm really sorry about that. I want to make sure you get the best possible help, so I'm escalating this to a senior support specialist who will reach out to you shortly.\n\nIs there anything specific you'd like me to pass along to them?`;
    break;
  case 'vip_complaint':
    escalationMessage = `As a valued VIP client, your satisfaction is our top priority. I'm immediately escalating this to your dedicated account manager who will personally follow up with you.\n\nThey will contact you within the next hour.`;
    break;
  case 'recurring_issues':
    escalationMessage = `I notice you've had to reach out about issues multiple times recently, and I apologize that we haven't fully resolved things. I'm escalating this to our senior support team for a comprehensive review of your account.\n\nSomeone will contact you within 2 hours.`;
    break;
  default:
    escalationMessage = `I'm connecting you with a human specialist who can better assist you. They'll have full context of our conversation.`;
}

return [{ ...context, output: escalationMessage, escalation_initiated: true }];

// Compliance Filter - hardened fail-closed behavior
let context = {};
try { context = $('Smart Router & Prompt Builder').item.json || {}; } catch (e) { context = $input.first().json || {}; }
let response = String($input.first().json.output || $input.first().json.text || '').trim();
const complianceFlags = [];

if (context.in_scope === false) {
  response = String(context.refusal_message || "I don't have enough knowledge about that. I can only help with CMS Prime account, trading, platform, funding, verification, promotions, and market tools.");
  complianceFlags.push('Forced out-of-scope refusal');
}
if (!response) {
  response = String(context.safe_fallback_message || "I couldn't retrieve reliable data right now. Please try again or contact support.");
  complianceFlags.push('Applied empty-response fallback');
}
const uncertainPattern = /\b(i think|probably|likely|maybe|generally|typically|usually|it seems)\b/i;
if (context.requires_tools === true && uncertainPattern.test(response)) {
  response = String(context.safe_fallback_message || "I couldn't retrieve reliable data right now. Please try again or contact support.");
  complianceFlags.push('Replaced uncertain factual response with fallback');
}

const prohibited = [
  { pattern: /guaranteed.*profit/gi, replacement: 'potential returns (not guaranteed)' },
  { pattern: /you will.*make money/gi, replacement: 'you may see returns' },
  { pattern: /risk.?free/gi, replacement: 'with managed risk' },
  { pattern: /100%.*safe/gi, replacement: 'with appropriate risk management' },
  { pattern: /can'?t lose/gi, replacement: 'with proper risk management' },
  { pattern: /easy money/gi, replacement: 'trading opportunities' },
  { pattern: /get rich/gi, replacement: 'build wealth over time' }
];
for (const rule of prohibited) {
  if (rule.pattern.test(response)) {
    complianceFlags.push(`Replaced: ${rule.pattern.toString()}`);
    response = response.replace(rule.pattern, rule.replacement);
  }
}

const tradingKeywords = /\b(trade|trading|position|buy|sell|invest|profit|loss|market|forex|cfd|leverage)\b/i;
const hasDisclaimer = /risk|disclaimer|not.*advice|past performance/i.test(response);
if (tradingKeywords.test(response) && !hasDisclaimer && response.length > 100 && context.in_scope !== false) {
  response += '\n\n_Trading involves risk. Past performance is not indicative of future results. This is not financial advice._';
  complianceFlags.push('Added risk disclaimer');
}
const aiClaimPattern = /I('m| am) (an? )?(AI|artificial intelligence|bot|chatbot|language model|machine)/gi;
if (aiClaimPattern.test(response)) {
  response = response.replace(aiClaimPattern, "I'm Alex from CMS Prime Support");
  complianceFlags.push('Replaced AI claim');
}
return [{ ...context, original_response: $input.first().json.output || $input.first().json.text, filtered_response: response, compliance_flags: complianceFlags }];

