let originalData = {};
try {
  const complianceItems = $('Compliance Filter').all();
  if (complianceItems && complianceItems.length > 0) {
    const pairedItem = $input.first().pairedItem;
    if (pairedItem && pairedItem.item && pairedItem.item.length > 0) {
      const sourceIndex = pairedItem.item[0].index || 0;
      originalData = complianceItems[sourceIndex]?.json || complianceItems[0].json || {};
    } else {
      originalData = complianceItems[0].json || {};
    }
  } else {
    originalData = $('Compliance Filter').item.json || {};
  }
} catch (e) {
  originalData = $input.first().json || {};
}

const sessionResult = $input.first().json || {};

return [{
  ...originalData,
  session_updated: true,
  session_id: sessionResult.session_id || originalData.session_id,
  user_phone: sessionResult.user_phone || originalData.user_phone,
  channel: sessionResult.channel || originalData.channel
}];

const context = $input.first().json;
const channel = context.channel;
let response = context.filtered_response || context.output || 'I apologize, but I encountered an issue. Please try again or contact support.';

if (channel === 'whatsapp') {
  response = response.replace(/\*\*([^*]+)\*\*/g, '*$1*').replace(/^- /gm, '• ');
}
else if (channel === 'telegram') {
  response = response.replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>').replace(/\*([^*]+)\*/g, '<i>$1</i>').replace(/_([^_]+)_/g, '<i>$1</i>');
}
else if (channel === 'email') {
  response += `\n\n---\nBest regards,\nAlex\nCMS Prime Support Team\n\nThis is an automated response. For urgent matters, please call +971 4 xxx xxxx.`;
}

return [{ output: response, channel: channel, session_id: context.session_id, user_phone: context.user_phone, metadata: context.metadata, message_type: context.message_type || 'text' }];

// =============================================================
// FIXED: Registration - Restore Input Context
// Changes: preserves draft_registration across turns; guarantees
// sessionId is consistent so Postgres Chat Memory matches sessions
// =============================================================
const current = $input.first().json || {};
let base = {};
try {
  base = $('Extract User Identifiers').item.json || {};
} catch (e) {
  base = {};
}

// Reliably pick sessionId — prefer the Web Chat Trigger value (base)
// because that is what Postgres Chat Memory uses as its lookup key.
const sessionId =
  base.sessionId ||
  base.session_id ||
  current.sessionId ||
  current.session_id ||
  `reg_${Date.now()}`;

const messageText =
  base.user_text ||
  base.message_text ||
  current.user_text ||
  current.message_text ||
  '';

// Preserve any existing draft — do NOT overwrite with an empty object
const existingDraft =
  base.registration_context ||
  current.registration_context ||
  base.draft_registration ||
  current.draft_registration ||
  {};

return [{
  ...base,
  ...current,
  user_text: messageText,
  message_text: messageText,
  session_id: sessionId,
  sessionId: sessionId,
  registration_in_progress: true,
  registration_context: existingDraft,
  draft_registration: existingDraft
}];

// =============================================================
// FIXED: Registration Context Builder
// Changes:
//   1. Never resets registration_context / draft_registration to {}
//   2. Injects the current draft into the system prompt so the agent
//      can always see what has already been collected
//   3. Strengthened rules: agent MUST pass ALL known fields on every
//      tool call, NEVER ask for a field already provided
// =============================================================
const input = $input.first().json || {};

// Carry forward any accumulated draft from previous turns
const existingDraft =
  input.registration_context ||
  input.draft_registration ||
  {};

const registrationPrompt = `You are Alex from CMS Prime Registration Support.

VOICE AND STYLE:
- Sound like a polite, friendly, human support specialist.
- Be warm, calm, and a bit casual — never robotic.
- Keep responses short and clear.
- Use supportive phrases naturally: "No problem", "Thanks", "Great, got it".

CURRENT DRAFT DATA (already collected — do NOT ask for these again):
${JSON.stringify(existingDraft, null, 2)}

REGISTRATION MODE RULES:
1. Your ONLY task is collecting the 4 required fields: email, firstName, lastName, nationality.
2. CRITICAL MEMORY RULE: On EVERY turn, consult CURRENT DRAFT DATA above AND the full chat
   history. NEVER ask for a field that is already in the draft or was already given in chat.
3. CRITICAL TOOL RULE: On EVERY turn you MUST call Tool - User Registration.
   You MUST pass ALL values already collected — both from the draft AND what the user just said.
   Example: if email and firstName are in the draft, pass email and firstName AND the new value.
   Passing empty strings for known fields is FORBIDDEN.
4. Ask for ONE missing field at a time.
5. Do NOT answer unrelated questions while registration is in progress.
6. Before final submission, display a full summary and require explicit "yes" confirmation.
7. If registration_ok is true in the tool response, confirm success warmly and stop.
8. Do NOT repeat welcome messages after the first turn.
9. Do NOT restart the conversation.

FIELD COLLECTION ORDER (skip fields already in the draft):
1. email
2. firstName
3. lastName
4. nationality
`;

const sessionId = input.sessionId || input.session_id || `reg_${Date.now()}`;
const userText = input.user_text || input.message_text || '';

return [{
  ...input,
  sessionId: sessionId,
  session_id: sessionId,
  user_text: userText,
  message_text: userText,
  registration_in_progress: true,
  registration_context: existingDraft,
  draft_registration: existingDraft,
  system_prompt: registrationPrompt
}];
